function access(){return shell(title('Account access needs attention','اکاؤنٹ کی رسائی پر توجہ درکار ہے','A sample restricted-account experience, not an approved enforcement policy.','محدود اکاؤنٹ کا نمونہ، منظور شدہ پابندی کی پالیسی نہیں۔')+panel('Your next step','آپ کا اگلا قدم',`${notice('This sample separates operational access from billing, recovery and support.','یہ نمونہ کام کی رسائی کو بلنگ، بحالی اور مدد سے الگ رکھتا ہے۔','warn')}<p>${t(role==='owner'?'Review the account issue with your billing contact or platform support.':'Contact your company owner. Your account cannot change the subscription.',role==='owner'?'بلنگ کے ذمہ دار یا پلیٹ فارم کی مدد سے اکاؤنٹ کا مسئلہ دیکھیں۔':'کمپنی کے مالک سے رابطہ کریں۔ آپ سبسکرپشن تبدیل نہیں کر سکتے۔')}</p><div class="actions">${role==='owner'?a('Open billing preview','بلنگ کا نمونہ کھولیں','billing','btn primary'):''}${a('Get help','مدد حاصل کریں','help','btn')}${a('Sign out','سائن آؤٹ','login','btn quiet')}</div>${policy('D01 · D03','What remains readable or writable, and whether current work may finish, is unresolved.','کیا پڑھنا یا بدلنا ممکن ہوگا اور جاری کام مکمل ہو سکے گا یا نہیں، طے نہیں۔')}`))}
function overview(){return shell(title('Location overview','مقام کا جائزہ','Historical performance for your assigned sites; daily actions stay in Today.','مقررہ مقامات کی تاریخی کارکردگی؛ روزمرہ اقدامات آج میں ہیں۔',a('Open Today','آج کھولیں','manager','btn primary','arrow'))+`<div class="split equal">${panel('Work submitted','جمع شدہ کام',`<strong style="font-size:28px"><bdi>42 / 56</bdi></strong><p class="muted">${t('Scheduled tasks · 14–20 Oct sample','شیڈول شدہ کام · ۱۴–۲۰ اکتوبر کا نمونہ')}</p><div class="chart-bars" aria-hidden="true">${[50,75,62.5,87.5,87.5,87.5,75].map((n,i)=>`<div><i style="--bar:${n}px"></i><small>${14+i}</small></div>`).join('')}</div><details class="section-space"><summary>${t('Daily figures','روزانہ کے اعداد')}</summary><p><bdi>14: 4/8 · 15: 6/8 · 16: 5/8 · 17: 7/8 · 18: 7/8 · 19: 7/8 · 20: 6/8</bdi></p></details><p class="small muted section-space">${t('Bars show the daily submission counts above. Submitted does not mean verified.','ستون اوپر کے روزانہ جمع شدہ کام دکھاتے ہیں۔ جمع ہونا تصدیق ہونا نہیں۔')}</p>`)}${panel('Assigned-site actions','مقررہ مقام کے اقدامات',`<div class="list-row"><div><h3>${t('Photo reviews','تصویروں کے جائزے')}</h3><p>${t('Inspect received evidence and record a decision.','موصولہ ثبوت دیکھیں اور فیصلہ درج کریں۔')}</p></div>${a('Open','کھولیں','reviews','btn')}</div><div class="list-row"><div><h3>${t('Attendance follow-up','حاضری کی پیروی')}</h3><p>${t('A missed checkout needs context.','روانگی درج نہ ہونے کی وضاحت درکار ہے۔')}</p></div>${a('Open','کھولیں','attendance-case','btn')}</div>`)}</div>`)}
function auth(){const op=page==='operator-login';if(page==='handoff')return publicShell('Your working day is in the app.','آپ کا کام ایپ میں ہے۔',`<p>${t('Use the installed Android app for attendance, tasks and required photos. Staff do not enter the company-management workspace.','حاضری، کام اور ضروری تصاویر کے لیے نصب شدہ اینڈرائیڈ ایپ استعمال کریں۔ کارکن کمپنی کے انتظامی حصے میں داخل نہیں ہوتے۔')}</p>${notice('The approved download and app-open destinations are not configured. Ask your manager for the verified release.','منظور شدہ ڈاؤن لوڈ اور ایپ کھولنے کا راستہ مقرر نہیں۔ مینیجر سے تصدیق شدہ ایپ لیں۔')}${policy('D09')}<div class="actions">${a('Explore staff app sample','عملے کی ایپ کا نمونہ','mobile','btn primary','arrow')}${a('Sign out preview','سائن آؤٹ کا نمونہ','login','btn quiet')}</div>`);
if(page==='recovery')return publicShell(params.get('link')==='expired'?'This recovery link has expired':'Recover your owner account',params.get('link')==='expired'?'بحالی کے لنک کی مدت ختم ہو گئی':'مالک کا اکاؤنٹ بحال کریں',params.get('link')==='expired'?`${notice('No password was changed. Request a new link using your verified contact.','پاس ورڈ تبدیل نہیں ہوا۔ تصدیق شدہ رابطے سے نیا لنک مانگیں۔','warn')}${a('Request a new link','نیا لنک مانگیں','recovery','btn primary')}`:authStep===1?`${notice('If an eligible account matches this contact, recovery instructions would be sent. This sample sends no message.','اگر اس رابطے کا مجاز اکاؤنٹ موجود ہو تو بحالی کی ہدایات بھیجی جائیں گی۔ اس نمونے سے پیغام نہیں بھیجا جاتا۔','good')}<div class="actions">${b('Preview reset form','پاس ورڈ بحالی کا نمونہ','reset-form','btn primary')}${a('Preview expired link','میعاد ختم شدہ لنک','recovery','btn','',{link:'expired'})}</div>${policy('D04 · D10')}`:authStep===2?`<form id="reset-form"><p class="muted">${t('Fictional values only. No real reset token is present.','صرف فرضی الفاظ۔ کوئی اصل بحالی کا ٹوکن موجود نہیں۔')}</p><div class="flow section-space">${input('reset-password','New password','نیا پاس ورڈ','','password','required autocomplete="new-password"')}${input('reset-confirm','Confirm password','پاس ورڈ کی تصدیق','','password','required autocomplete="new-password"')}</div><p class="form-error" id="reset-error" role="alert"></p><div class="actions"><button class="btn primary" type="submit">${t('Preview reset','بحالی کا نمونہ')}</button></div></form>`:authStep===3?notice('Sample reset complete. Real token expiry, delivery and session revocation require approved policy and implementation.','نمونے میں بحالی مکمل۔ اصل ٹوکن کی مدت، ترسیل اور سیشن ختم کرنے کے لیے منظور شدہ پالیسی اور عمل ضروری ہیں۔','good'):`<form id="recovery-form"><p class="muted">${t('Use a fictional owner contact to preview the neutral acknowledgement.','وصولی کا غیر جانبدار پیغام دیکھنے کے لیے مالک کا فرضی رابطہ لکھیں۔')}</p><div class="section-space">${input('recovery-email','Owner email','مالک کی ای میل','owner@example.invalid','email','required autocomplete="off"')}</div><div class="actions"><button class="btn primary full" type="submit">${t('Preview recovery request','بحالی کی درخواست کا نمونہ')}</button></div>${policy('D04 · D10')}</form>`);
if(page==='verify')return publicShell('Verify your contact','اپنے رابطے کی تصدیق کریں',params.get('link')==='expired'?`${notice('This verification link is no longer usable. No contact was verified.','یہ تصدیقی لنک اب قابلِ استعمال نہیں۔ کسی رابطے کی تصدیق نہیں ہوئی۔','warn')}${a('Request verification preview','تصدیق کا نمونہ مانگیں','verify','btn primary')}`:state.verified?`${notice('Fictional contact verified in this session. No real email ownership check occurred.','اس سیشن میں فرضی رابطے کی تصدیق ہوئی۔ اصل ای میل کی ملکیت جانچی نہیں گئی۔','good')}${a('Continue company setup','کمپنی کا سیٹ اپ جاری رکھیں','setup','btn primary')}`:`<p>${t('Your contact helps secure recovery and important account messages. The delivery channel and existing-owner checks are still unresolved.','رابطہ بحالی اور اہم پیغامات کو محفوظ بنانے میں مدد دیتا ہے۔ ترسیل کا ذریعہ اور پرانے مالک کی جانچ ابھی طے نہیں۔')}</p>${policy('D04')}<div class="actions">${b('Simulate verified link','تصدیق شدہ لنک کا نمونہ','verify-contact','btn primary','check')}${a('Expired link preview','ختم شدہ لنک کا نمونہ','verify','btn','',{link:'expired'})}</div>`);
if(op)return publicShell('Platform operator sign-in','پلیٹ فارم آپریٹر کا داخلہ',`${badge('Restricted operator identity','محدود آپریٹر شناخت','blue')}<p class="section-space">${t('Only provisioned operators can access customer-account administration. Company owners use a separate sign-in.','صرف مجاز بنائے گئے آپریٹر کسٹمر اکاؤنٹ کا انتظام کر سکتے ہیں۔ کمپنی مالکان کا داخلہ الگ ہے۔')}</p>${authStep===0?`<form id="operator-form"><div class="field section-space"><label for="operator-account">${t('Sample operator account','نمونے کا آپریٹر اکاؤنٹ')}</label><select id="operator-account"><option>Amina Omar · operator@example.invalid</option></select></div><div class="actions"><button class="btn primary full" type="submit">${t('Continue sample sign-in','نمونے کا داخلہ جاری رکھیں')}</button></div></form>`:authStep===1?`<form id="mfa-form"><div class="section-space">${input('mfa-code','Demo second-factor code','نمونے کا اضافی تصدیقی کوڈ','','text','required inputmode="numeric" maxlength="6" pattern="[0-9]{6}" aria-describedby="mfa-hint"')}<p id="mfa-hint" class="small muted">${t('Enter 123456 for this offline demonstration only.','صرف اس آف لائن نمونے کے لیے 123456 لکھیں۔')}</p><p id="mfa-error" class="form-error" role="alert"></p></div><div class="actions"><button class="btn primary full" type="submit">${t('Verify sample challenge','نمونے کی تصدیق کریں')}</button></div></form>`:a('Open operator workspace','آپریٹر ورک اسپیس کھولیں','platform','btn primary full')}${policy('D05 · D10','MFA method and identity provider remain unresolved. This is a visual challenge simulation, not authentication.','اضافی تصدیق کا طریقہ اور شناخت کی سروس طے نہیں۔ یہ صرف بصری نمونہ ہے، اصل شناخت نہیں۔')}<div class="auth-footer">${a('Company sign-in','کمپنی کا داخلہ','login','')}</div>`);
return publicShell('Welcome back','خوش آمدید',`<p>${t('Choose a fictional identity to inspect the correct destination. No real credentials are requested.','درست منزل دیکھنے کے لیے فرضی شناخت منتخب کریں۔ اصل شناختی معلومات درکار نہیں۔')}</p><form id="tenant-login"><div class="field section-space"><label for="login-role">${t('Sample account','نمونے کا اکاؤنٹ')}</label><select id="login-role"><option value="owner">${L('Company owner','کمپنی کا مالک')}</option><option value="manager">${L('Assigned-site manager','مقررہ مقام کا مینیجر')}</option><option value="staff">${L('Staff','عملہ')}</option></select></div><div class="actions"><button type="submit" class="btn primary full">${t('Open sample workspace','نمونے کی ورک اسپیس کھولیں')}</button></div></form><div class="auth-footer">${a('Owner account recovery','مالک کے اکاؤنٹ کی بحالی','recovery','')}${a('Company setup preview','کمپنی کے سیٹ اپ کا نمونہ','setup','')}</div><div class="section-space">${policy('D04 · D10')}</div>`)}
function publicShell(en,ur,body){return `${previewBar()}<main class="auth" id="main">${brand()}<h1>${t(en,ur)}</h1><div class="panel section-space">${globalState()||body}</div><div class="actions between">${language()}${a('Prototype gallery','نمونوں کی گیلری','index','btn quiet')}</div>${feedback?`<div class="feedback section-space" role="status">${E(feedback)}</div>`:''}</main>${dialogHTML()}`}
const fixtureNames=[['Basin · Front view','بیسن · سامنے کا منظر'],['Toilet · Required view','ٹوائلٹ · ضروری منظر'],['Floor · Wide view','فرش · مکمل منظر']],fixtures=['basin','toilet','floor'];
function mobile(){let content='';if(mobileTab==='help')content=`<h1>${t('Help & account','مدد اور اکاؤنٹ')}</h1><section class="panel"><h2>${t('Task alerts','کام کی اطلاعات')}</h2><p class="section-space">${t(alertEnabled?'Alerts enabled in sample':'Alerts are not available on this phone',alertEnabled?'نمونے میں اطلاعات فعال':'اس فون پر اطلاعات دستیاب نہیں')}</p><p class="small muted section-space">${t('Your work remains available. Permission and delivery are different things.','آپ کا کام دستیاب ہے۔ اجازت اور ترسیل الگ چیزیں ہیں۔')}</p><div class="actions">${b('Preview Android settings','اینڈرائیڈ ترتیبات کا نمونہ','alerts-settings','btn')}${b('Retry registration','رجسٹریشن دوبارہ کریں','alerts-retry','btn primary')}</div></section><section class="panel"><h2><bdi>Adeel Raza</bdi></h2><p><bdi>Gulberg office</bdi></p><p class="section-space">${t('Need access help? Ask your assigned manager. Do not share passwords or private photos.','رسائی میں مدد چاہیے؟ مقررہ مینیجر سے پوچھیں۔ پاس ورڈ یا نجی تصویریں نہ بھیجیں۔')}</p><div class="actions">${b('Account help','اکاؤنٹ کی مدد','staff-help','btn')}</div></section>${policy('D04 · D05 · D10')}`;
else if(mobileTab==='tasks'&&phase==='shift')content=`<h1>${t('Your tasks','آپ کے کام')}</h1>${mobileTask()}<section class="panel"><h2>${t('Entrance & lobby','داخلی راستہ اور لابی')}</h2><p><bdi>11:00–12:00 · Gulberg office</bdi></p><p class="section-space muted">${t('Upcoming work. Its own task QR will be required.','آنے والا کام۔ اس کام کا اپنا کیو آر ضروری ہوگا۔')}</p></section>`;
else if(phase==='shift')content=`<div><p class="muted">${t('Tuesday, 20 October','منگل، ۲۰ اکتوبر')}</p><h1>${t('Your working day','آپ کا کام کا دن')}</h1><p class="muted"><bdi>Gulberg office</bdi></p></div><section class="panel"><div class="flex between"><h2>${t('Your shift','آپ کی شفٹ')}</h2>${badge(checkedOut?'Checked out':checkedIn?'Checked in':'Not checked in',checkedOut?'روانگی درج':checkedIn?'آمد درج':'آمد درج نہیں',checkedIn||checkedOut?'good':'warn')}</div><p class="section-space"><bdi>08:00–16:00</bdi></p><p class="section-space">${t(checkedOut?'Sample shift is closed. Your records stay available.':checkedIn?'Your attendance is recorded in this sample. Continue with your next task.':'You need camera and location access to record attendance.',checkedOut?'نمونے کی شفٹ بند ہے۔ ریکارڈ دستیاب رہے گا۔':checkedIn?'اس نمونے میں آمد درج ہے۔ اپنا اگلا کام جاری رکھیں۔':'حاضری کے لیے کیمرے اور مقام کی اجازت ضروری ہے۔')}</p>${!checkedIn&&!checkedOut?`<div class="actions">${b('Check in preview','آمد درج کرنے کا نمونہ','checkin-camera','btn primary full','camera')}</div>`:!checkedOut?`<div class="actions">${b('Preview checkout','روانگی کا نمونہ','checkout-camera','btn full')}</div>`:''}</section>${!checkedOut?mobileTask():notice('Sample checkout recorded. No real attendance data was written.','نمونے میں روانگی درج۔ اصل حاضری میں کچھ نہیں لکھا گیا۔','good')}`;
else if(['checkin-camera','checkout-camera'].includes(phase))content=`<h1>${t(phase==='checkin-camera'?'Record your arrival':'Record your checkout',phase==='checkin-camera'?'اپنی آمد درج کریں':'اپنی روانگی درج کریں')}</h1><section class="panel"><div class="state-box" style="padding:24px 0">${icon('camera')}<h2>${t('Fresh selfie and current location','تازہ تصویر اور موجودہ مقام')}</h2><p>${t('Camera simulation only. No camera or GPS is accessed.','صرف کیمرے کا نمونہ۔ کیمرہ یا جی پی ایس استعمال نہیں ہوتا۔')}</p></div>${b('Simulate authorized capture','مجاز تصویر لینے کا نمونہ','attendance-captured','btn primary full','camera')}<div class="actions">${b('Back','واپس','mobile-day','btn')}</div></section><details><summary>${t('Reviewer: permission failure','جائزہ کار: اجازت کی خرابی')}</summary><div class="actions">${b('Show denied permission','اجازت مسترد دکھائیں','permission-denied','btn')}</div></details>`;
else if(phase==='permission')content=`<h1>${t('Permission needed','اجازت ضروری ہے')}</h1>${notice('Location or camera access is off. Attendance has not been recorded.','مقام یا کیمرے کی اجازت بند ہے۔ حاضری درج نہیں ہوئی۔','warn')}${b('Preview opening app settings','ایپ کی ترتیبات کھولنے کا نمونہ','permission-settings','btn primary full')}${b('Try again','دوبارہ کوشش','checkin-camera','btn')}`;
else if(phase==='start-qr')content=`<h1>${t('Scan this task’s QR','اس کام کا کیو آر اسکین کریں')}</h1><p>${t('Use the code shown by your manager for Ground-floor washrooms. A room code or another task cannot start this work.','گراؤنڈ فلور واش روم کے لیے مینیجر کا دیا ہوا کوڈ استعمال کریں۔ کمرے یا دوسرے کام کا کوڈ اسے شروع نہیں کرے گا۔')}</p><section class="panel state-box">${icon('camera')}<strong>${t('QR scanner preview','کیو آر اسکینر کا نمونہ')}</strong>${b('Simulate correct task QR','درست کام کے کیو آر کا نمونہ','start-authorized','btn primary full')}</section><details><summary>${t('Reviewer: wrong QR','جائزہ کار: غلط کیو آر')}</summary><div class="actions">${b('Preview wrong task code','غلط کام کے کوڈ کا نمونہ','wrong-qr','btn')}</div></details>${b('Back to tasks','کاموں پر واپس','mobile-tasks','btn')}`;
else if(phase==='cleaning')content=`${badge('Cleaning started','صفائی شروع','blue')}<h1>${t('Ground-floor washrooms','گراؤنڈ فلور کے واش روم')}</h1><p>${t('Clean the assigned area. When ready, scan this task’s QR again to take the required photos.','مقررہ جگہ صاف کریں۔ تیار ہونے پر ضروری تصاویر کے لیے اسی کام کا کیو آر دوبارہ اسکین کریں۔')}</p>${b('Ready for photos','تصویروں کے لیے تیار','photo-qr','btn primary full','camera')}<p class="muted">${t('Starting work is separate from submitting it.','کام شروع کرنا اور اسے جمع کرنا الگ ہیں۔')}</p>`;
else if(phase==='photo-qr')content=`<h1>${t('Confirm photo access','تصویروں کی رسائی کی تصدیق کریں')}</h1><p>${t('Scan the same task QR again. Photo authority follows your current task assignment.','اسی کام کا کیو آر دوبارہ اسکین کریں۔ تصویر کی اجازت آپ کے موجودہ کام سے وابستہ ہے۔')}</p><section class="panel state-box">${icon('camera')}${b('Simulate authorized photo scan','مجاز تصویری اسکین کا نمونہ','photo-authorized','btn primary full')}</section>${policy('D11','Existing task-bound capture flow; timings are not simulated here.','موجودہ کام سے وابستہ تصویری عمل؛ وقت کی حد یہاں چلائی نہیں جاتی۔')}`;
else if(phase==='photo'||phase==='result-unknown'||phase==='photo-result'){let idx=Math.min(photoCount,2);content=`<div class="flex between"><span>${t('Required photos','ضروری تصویریں')}</span><strong><bdi>${idx+1} / 3</bdi></strong></div><div class="phone-step" aria-label="${L('Photo progress','تصویروں کی پیش رفت')}">${[0,1,2].map(i=>`<span class="${i<photoCount?'done':''}"></span>`).join('')}</div><h1>${t(...fixtureNames[idx])}</h1><p>${t('Include the whole required surface. Use a fresh photo after cleaning.','مکمل ضروری سطح دکھائیں۔ صفائی کے بعد تازہ تصویر لیں۔')}</p><img class="photo-sample" src="assets/${fixtures[idx]}.webp" alt="${L('Synthetic '+fixtures[idx]+' guidance image','رہنمائی کی فرضی تصویر')}"><small class="muted">${t('Synthetic guidance image · not a staff upload','رہنمائی کی فرضی تصویر · کارکن کی اپ لوڈ نہیں')}</small>${phase==='result-unknown'?`${notice('The upload response was lost. Do not take another photo yet; check this result first.','اپ لوڈ کا جواب نہیں ملا۔ ابھی دوسری تصویر نہ لیں؛ پہلے اسی کا نتیجہ دیکھیں۔','warn')}${b('Check upload result','اپ لوڈ کا نتیجہ دیکھیں','check-photo-result','btn primary full')}`:phase==='photo-result'?`${notice('Sample photo received and checked. Receipt does not imply verified task completion.','نمونے کی تصویر موصول اور جانچ لی گئی۔ موصول ہونے سے کام کی مصدقہ تکمیل نہیں ہوتی۔','good')}${b(photoCount===2?'Review required photos':'Next required photo',photoCount===2?'ضروری تصاویر کا جائزہ':'اگلی ضروری تصویر','next-photo','btn primary full')}`:`${b('Capture photo preview','تصویر لینے کا نمونہ','capture-photo','btn primary full','camera')}<details><summary>${t('Reviewer: upload exception states','جائزہ کار: اپ لوڈ کی غیر معمولی حالتیں')}</summary><div class="actions">${b('Lost response','جواب نہیں ملا','lost-response','btn')}${b('Photo rejected','تصویر مسترد','photo-rejected','btn')}${b('Check unavailable','جانچ دستیاب نہیں','photo-uncertain','btn')}</div></details>`}`;}
else if(phase==='photo-rejected')content=`<h1>${t('Show the required view','ضروری منظر دکھائیں')}</h1>${notice('Wrong view in this fictional result. The required surface is not fully visible.','اس فرضی نتیجے میں منظر غلط ہے۔ ضروری سطح پوری نظر نہیں آ رہی۔','warn')}<p>${t('A retry must use current server-authorized photo access. No manager deadline extension is offered.','دوبارہ کوشش کے لیے سروس کی موجودہ اجازت ضروری ہوگی۔ مینیجر کو وقت بڑھانے کا اختیار نہیں دیا گیا۔')}</p>${b('Preview eligible retake','مجاز دوبارہ تصویر کا نمونہ','eligible-retake','btn primary full')}${policy('D11','Illustrative failed-view eligibility; final authority and deadlines remain unresolved.','ناکام منظر کی اجازت کا نمونہ؛ حتمی اجازت اور وقت کی حد غیر طے شدہ ہیں۔')}`;
else if(phase==='photo-uncertain')content=`<h1>${t('Photo check unavailable','تصویر کی جانچ دستیاب نہیں')}</h1>${notice('This sample keeps the received photo for review. A service failure is not a dirty finding.','یہ نمونہ موصولہ تصویر کو جائزے کے لیے رکھتا ہے۔ سروس کی خرابی گندگی کا نتیجہ نہیں۔','warn')}${b('Continue sample receipt flow','موصولہ تصویر کا نمونہ جاری رکھیں','photo-checked','btn primary full')}${policy('D11')}`;
else if(phase==='submit')content=`<h1>${t('Review before submitting','جمع کرنے سے پہلے جائزہ لیں')}</h1><div class="figure-grid">${fixtures.map((x,i)=>`<figure><img src="assets/${x}.webp" alt="${L('Synthetic required view '+(i+1),'ضروری منظر کی فرضی تصویر '+(i+1))}"><figcaption>${t(...fixtureNames[i])}</figcaption></figure>`).join('')}</div>${badge('3 / 3 photos received','۳ / ۳ تصویریں موصول','good')}<p>${t('Every required sample photo has a checked result. Work submission and manager review remain separate.','ہر ضروری نمونہ تصویر کا نتیجہ موجود ہے۔ کام جمع ہونا اور مینیجر کا جائزہ الگ ہیں۔')}</p>${b('Submit sample work','نمونے کا کام جمع کریں','submit-work','btn primary full','check')}${policy('D11')}`;
else if(phase==='submitted')content=`${badge('Work submitted','کام جمع ہو گیا','good')}<h1>${t('Your work is submitted','آپ کا کام جمع ہو گیا')}</h1><p>${t('Your manager may still need to review the photos. This does not label the task as verified.','مینیجر کو ابھی تصاویر کا جائزہ لینا ہو سکتا ہے۔ اس سے کام مصدقہ قرار نہیں دیا گیا۔')}</p>${b('Return to My day','میرے دن پر واپس','mobile-day','btn primary full')}<details><summary>${t('Reviewer: proposed later replacement','جائزہ کار: بعد کی مجوزہ تبدیلی')}</summary>${policy('D11','Post-submission photo replacement is not an approved policy.','کام جمع ہونے کے بعد تصویر کی تبدیلی منظور شدہ پالیسی نہیں۔')}<div class="actions">${b('Inspect illustrative request','نمائشی درخواست دیکھیں','post-submit-rework','btn')}</div></details>`;
else if(phase==='post-submit-rework')content=`<h1>${t('A photo needs follow-up','تصویر کی پیروی درکار ہے')}</h1><p>${t('Illustrative future request for one failed view. Existing evidence would remain in history. Authorization, deadlines and post-submission eligibility await D11.','ایک ناکام منظر کے لیے آئندہ درخواست کا نمونہ۔ پرانا ثبوت تاریخ میں رہے گا۔ اجازت، وقت کی حد اور جمع ہونے کے بعد اہلیت D11 کے فیصلے سے طے ہوں گی۔')}</p>${b('Return to submitted state','جمع شدہ حالت پر واپس','back-submitted','btn primary full')}${policy('D11')}`;
return `${previewBar()}<a class="skip" href="#main">${t('Skip to content','اصل مواد پر جائیں')}</a><div class="phone-canvas"><div class="phone"><header class="phone-top">${brand('mobile')}${language()}</header><main id="main" class="phone-main" tabindex="-1">${feedback?`<div class="feedback ${feedbackError?'error':''}" role="${feedbackError?'alert':'status'}">${E(feedback)}</div>`:''}${preview==='offline'?notice('Internet needed to continue. This is last-loaded sample information.','جاری رکھنے کے لیے انٹرنیٹ ضروری ہے۔ یہ پچھلی لوڈ شدہ معلومات ہیں۔','warn'):''}${globalState()||content}</main><nav class="phone-tabs" aria-label="${L('Staff navigation','عملے کی نیویگیشن')}">${[['day','clock','My day','میرا دن'],['tasks','grid','Tasks','کام'],['help','help','Help & account','مدد اور اکاؤنٹ']].map(([id,ic,en,ur])=>b(en,ur,'mobile-'+id,'',ic,`aria-current="${mobileTab===id?'page':'false'}"`)).join('')}</nav></div><p class="mobile-preview-note">${t('Browser reference for the native app. No camera, GPS, push or live verification is used.','اصل ایپ کا براؤزر نمونہ۔ کیمرہ، جی پی ایس، اطلاع یا حقیقی جانچ استعمال نہیں ہوتی۔')}</p></div>${dialogHTML()}`}
function mobileTask(){if(submittedWork)return `<section class="panel"><h2>${t('Ground-floor washrooms','گراؤنڈ فلور کے واش روم')}</h2><div class="section-space">${badge('Work submitted','کام جمع ہو گیا','good')}</div><p class="section-space">${t('Manager review may still be needed. Verified completion is separate.','مینیجر کا جائزہ باقی ہو سکتا ہے۔ مصدقہ تکمیل الگ ہے۔')}</p><div class="actions">${b('View submission','جمع شدہ کام دیکھیں','back-submitted','btn full')}</div></section>`;return `<section class="panel"><div class="flex between"><h2>${t('Ground-floor washrooms','گراؤنڈ فلور کے واش روم')}</h2></div><p class="muted section-space"><bdi>09:00–10:00</bdi></p><p class="section-space">${t('3 required views · Gulberg office','۳ ضروری منظر · گلبرگ دفتر')}</p><div class="actions">${b('Start cleaning','صفائی شروع کریں','start-qr','btn primary full','arrow',!checkedIn?'disabled':'')}</div>${!checkedIn?`<p class="small muted section-space">${t('Check in before starting your assigned task.','مقررہ کام شروع کرنے سے پہلے آمد درج کریں۔')}</p>`:''}</section>`}
