function decisionPage(){return `${previewBar()}<main class="gallery" id="main"><div class="gallery-top">${brand()}${language()}</div>${title('Decisions still open','غیر طے شدہ فیصلے','Scope approval did not approve these business policies.','دائرۂ کار کی منظوری سے ان کاروباری پالیسیوں کی منظوری نہیں ہوئی۔')}<section class="panel"><div class="pad">${decisions.map(([id,en,ur])=>`<div class="list-row"><div><strong><bdi>${id}</bdi> · ${t(en,ur)}</strong></div>${badge('Unresolved','غیر طے شدہ','warn')}</div>`).join('')}</div></section>${notice('Prototype actions preview an interaction, not a selected business rule. Provider choices, prices, retention periods, grace days and support recipients remain unset.','نمونے کے اقدامات صرف تعامل دکھاتے ہیں، منتخب کاروباری اصول نہیں۔ سروس، قیمت، محفوظ رکھنے کی مدت، مہلت اور رابطہ طے نہیں ہوئے۔')}${a('Back to gallery','گیلری پر واپس','index','btn')}</main>`}
function information(){return publicShell('Service information','سروس کی معلومات',`<p>${t('The live product will need approved customer-facing information. These are review placeholders, not legal terms.','اصل پروڈکٹ میں کسٹمر کے لیے منظور شدہ معلومات ضروری ہیں۔ یہ جائزے کا خاکہ ہے، قانونی شرائط نہیں۔')}</p>${[['Service and billing','سروس اور بلنگ','D02 · D03'],['Photos and privacy','تصویریں اور رازداری','D08 · D11'],['Retention and account closure','محفوظ رکھنا اور اکاؤنٹ بند کرنا','D08'],['Support contact','مدد کا رابطہ','D04 · D05']].map(([en,ur,id])=>`<div class="list-row"><div><h3>${t(en,ur)}</h3><p class="muted small">${t('Content awaits policy approval.','مواد پالیسی کی منظوری کا منتظر ہے۔')}</p><a href="${href('decisions')}"><bdi>${id}</bdi></a></div></div>`).join('')}`)}
